export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { data, error } = await supabase
      .from('event_interested')
      .select('*')
      .eq('event_id', eventId)
      .eq('user_id', userId)
      .maybeSingle();
      
    if (error) throw error;
    return !!data;
  } catch (error) {
    console.error('Error checking if user is interested in event:', error);
    return false;
  }
};

export const markEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // Check if the user is already interested
    const isInterested = await isUserInterestedInEvent(eventId, userId);
    if (isInterested) return true;
    
    // Add user interest
    const { error } = await supabase
      .from('event_interested')
      .insert({ event_id: eventId, user_id: userId });
      
    if (error) throw error;
    
    // Update user profile events_upcoming count
    const { error: profileError } = await supabase.rpc('increment_user_upcoming_events', { user_id_param: userId });
    if (profileError) console.error('Error updating user upcoming events count:', profileError);
    
    return true;
  } catch (error) {
    console.error('Error marking event interest:', error);
    return false;
  }
};

export const removeEventInterest = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // Remove user interest
    const { error } = await supabase
      .from('event_interested')
      .delete()
      .eq('event_id', eventId)
      .eq('user_id', userId);
      
    if (error) throw error;
    
    // Update user profile events_upcoming count
    const { error: profileError } = await supabase.rpc('decrement_user_upcoming_events', { user_id_param: userId });
    if (profileError) console.error('Error updating user upcoming events count:', profileError);
    
    return true;
  } catch (error) {
    console.error('Error removing event interest:', error);
    return false;
  }
};

export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    // Check if the user is already checked in
    const { data: existingCheckIn, error: checkError } = await supabase
      .from('event_attendees_new')
      .select('*')
      .eq('event_id', eventId)
      .eq('user_id', userId)
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    // If already checked in, return true
    if (existingCheckIn) return true;
    
    // Add check-in record
    const { error } = await supabase
      .from('event_attendees_new')
      .insert({ event_id: eventId, user_id: userId });
      
    if (error) throw error;
    
    // Mark interest if not already interested
    await markEventInterest(eventId, userId);
    
    // Update user profile events_attended count
    const { error: profileError } = await supabase.rpc('increment_user_attended_events', { user_id_param: userId });
    if (profileError) console.error('Error updating user attended events count:', profileError);
    
    return true;
  } catch (error) {
    console.error('Error checking in user to event:', error);
    return false;
  }
};

// Event Attendee and Interested Users Functions
export const getEventAttendees = async (eventId: string, includeProfiles = false): Promise<any[]> => {
  try {
    let query = supabase
      .from('event_attendees_new')
      .select(includeProfiles ? 'id, check_in_time, user_id, profiles:user_id(id, name, email)' : '*')
      .eq('event_id', eventId)
      .order('check_in_time', { ascending: false });
    
    const { data, error } = await query;
    
    if (error) throw error;
    return data || [];
  } catch (error) {
    console.error('Error getting event attendees:', error);
    return [];
  }
};

