// User Events Functions
export const getUserAttendedEvents = async (userId: string): Promise<any[]> => {
  try {
    const { data, error } = await supabase
      .from('event_attendees_new')
      .select(`
        id, check_in_time,
        events:event_id(
          id, title, description, event_date, 
          location, image_url, is_active
        )
      `)
      .eq('user_id', userId)
      .order('check_in_time', { ascending: false });
    
    if (error) throw error;
    
    // Extract the event data from the nested structure
    return (data || [])
      .filter(item => item.events) // Filter out any null events
      .map(item => ({
        id: item.events.id,
        title: item.events.title,
        description: item.events.description,
        event_date: item.events.event_date,
        location: item.events.location,
        image_url: item.events.image_url,
        is_active: item.events.is_active,
        check_in_time: item.check_in_time
      }));
  } catch (error) {
    console.error('Error getting user attended events:', error);
    return [];
  }
};

