export const promoteStudentToInfoOfficer = async (userId: string): Promise<boolean> => {
  try {
    // Check if the user already has the role
    const { data: existingRole, error: checkError } = await supabase
      .from('user_roles')
      .select('*')
      .eq('user_id', userId)
      .eq('role', 'information_officer')
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    // If already has the role, return true
    if (existingRole) return true;
    
    // Add the information_officer role
    const { error } = await supabase
      .from('user_roles')
      .insert({ user_id: userId, role: 'information_officer' });
      
    if (error) throw error;
    
    return true;
  } catch (error) {
    console.error('Error promoting student to information officer:', error);
    return false;
  }
};

// Additional Utility Functions
export const createEventReminderNotifications = async (event: any, userId: string): Promise<boolean> => {
  try {
    if (!event || !userId) return false;
    
    // Create a notification for the event
    const { error } = await supabase
      .from('notifications')
      .insert({
        user_id: userId,
        title: "Event Reminder",
        message: `Reminder: "${event.title}" is coming up soon!`,
        type: "event_reminder",
        related_id: event.id
      });
      
    if (error) throw error;
    
    return true;
  } catch (error) {
    console.error('Error creating event reminder notification:', error);
    return false;
  }
};

